private theorem polar_atom_weights {n : ℕ} (hn : 0 < n) (x : ℝ) :
    (1 / Real.sqrt n : ℝ) * Real.exp ((x + Real.log n) / 2) = Real.exp (x/2) ∧
    (1 / Real.sqrt n : ℝ) * Real.exp ((x - Real.log n) / 2) = Real.exp (x/2) / n

